/**
 * withAndroidGradleHeap -- give the Gradle daemon a 4 GB heap (the generated android/gradle.properties
 * has 2 GB). The release build's D8 dex merge ("mergeDexRelease") runs out of memory with 2 GB:
 * `java.lang.OutOfMemoryError: Java heap space`. Debug builds are unaffected.
 *
 * Applied to the generated android/gradle.properties (gitignored, regenerated by `expo prebuild`).
 */
const { withGradleProperties } = require('expo/config-plugins')

module.exports = function withAndroidGradleHeap(config) {
  return withGradleProperties(config, (config) => {
    const key = 'org.gradle.jvmargs'
    const value = '-Xmx4g -XX:MaxMetaspaceSize=1g'
    const props = config.modResults
    const existing = props.find((p) => p.type === 'property' && p.key === key)
    if (existing) existing.value = value
    else props.push({ type: 'property', key, value })
    return config
  })
}
